const msg = $input.item.json.message;
const chatId = String(msg.chat.id);
const text = (msg.text || '').trim();
const firstName = (msg.from && msg.from.first_name) ? msg.from.first_name : 'صديقي';
return [{ json: { chatId, text, firstName } }];

// ============================================================
// Format JSON Code – C1 HSCH Exam Builder
// ============================================================
// يستقبل هذا الكود البيانات الخام من الـ AI Agent عبر الأداة
// ويقوم بـ:
//   1. تقسيم النصوص إلى segments عند كل _____
//   2. بناء مصفوفة answers مع خيارات كاملة في id:0 فقط
//   3. حساب مسار الملف وصياغة JSON النهائي
// ============================================================

const raw = $input.item.json;

// --- استخراج البيانات الخام ---
const text_de      = (raw.text_de || '').trim();
const text_ar      = (raw.text_ar || '').trim();
const optionsRaw   = raw.options;    // مصفوفة الخيارات [{key, de, ar, keywords:{de,ar}}, ...]
const answersRaw   = raw.answers;    // ['f','e','b','h','c','g','d'] أو [{id,correct_key},...]
const section      = Number(raw.section);
const section_name = (raw.section_name || '').trim();
const model        = Number(raw.model);
const model_name   = (raw.model_name || '').trim();
const slug         = (raw.slug || '').trim().toLowerCase();

// -------------------------------------------------------
// دالة تقسيم النص إلى segments
// -------------------------------------------------------
function buildSegments(text) {
  const BLANK_MARKER = '_____';
  const parts = text.split(BLANK_MARKER);
  const segments = [];
  let blankId = 0;

  parts.forEach((part, idx) => {
    if (part !== '') {
      segments.push({ type: 'text', content: part });
    }
    // بعد كل جزء (إلا الأخير) يأتي فراغ
    if (idx < parts.length - 1) {
      segments.push({ type: 'blank', id: blankId++ });
    }
  });

  return { segments, totalBlanks: blankId };
}

const deResult = buildSegments(text_de);
const arResult = buildSegments(text_ar);
const totalBlanks = deResult.totalBlanks;

// -------------------------------------------------------
// بناء مصفوفة الإجابات
// -------------------------------------------------------
// تطبيع الخيارات
let options = [];
if (Array.isArray(optionsRaw)) {
  options = optionsRaw.map(o => ({
    key: String(o.key || '').toLowerCase(),
    de: String(o.de || ''),
    ar: String(o.ar || ''),
    keywords: {
      de: String((o.keywords && o.keywords.de) || ''),
      ar: String((o.keywords && o.keywords.ar) || '')
    }
  }));
}

// تطبيع الإجابات
let correctKeys = [];
if (Array.isArray(answersRaw)) {
  if (answersRaw.length > 0 && typeof answersRaw[0] === 'string') {
    // صيغة: ['f','e','b',...]
    correctKeys = answersRaw.map(k => String(k).toLowerCase());
  } else if (typeof answersRaw[0] === 'object') {
    // صيغة: [{id:0,correct_key:'f'},{id:1,correct_key:'e'},...]
    correctKeys = answersRaw
      .sort((a, b) => a.id - b.id)
      .map(a => String(a.correct_key || '').toLowerCase());
  }
}

// بناء مصفوفة answers
const answers = [];
for (let i = 0; i < totalBlanks; i++) {
  if (i === 0) {
    // الفراغ الأول فقط يحتوي على قائمة الخيارات الكاملة
    answers.push({
      id: 0,
      correct_key: correctKeys[0] || '',
      options: options
    });
  } else {
    answers.push({
      id: i,
      correct_key: correctKeys[i] || ''
    });
  }
}

// -------------------------------------------------------
// بناء الـ meta
// -------------------------------------------------------
const meta = {
  app: 'c1_hsch',
  section: section,
  section_name: section_name,
  model: model,
  model_name: model_name,
  level: 'C1',
  total_blanks: totalBlanks
};

// -------------------------------------------------------
// بناء JSON النهائي
// -------------------------------------------------------
const finalJson = {
  meta: meta,
  text: {
    de: [{ type: 'paragraph', segments: deResult.segments }],
    ar: [{ type: 'paragraph', segments: arResult.segments }]
  },
  answers: answers
};

// -------------------------------------------------------
// حساب مسار الملف وإسمه ديناميكياً
// s{section}_m{model}_{slug}.json
// assets/data/section_{section}/
// -------------------------------------------------------
const filename = `s${section}_m${model}_${slug}.json`;
const filePath = `assets/data/section_${section}/${filename}`;
const fileContent = JSON.stringify(finalJson, null, 2);

// -------------------------------------------------------
// الإخراج
// -------------------------------------------------------
return [{
  json: {
    finalJson,
    fileContent,
    filePath,
    filename,
    section,
    section_name,
    model,
    model_name,
    totalBlanks,
    optionsCount: options.length,
    chatId: $('Parse Message').item.json.chatId
  }
}];
